import {staticFile} from 'remotion';
import * as THREE from 'three';
import {GLTFLoader} from 'three/examples/jsm/loaders/GLTFLoader.js';
import type {Aplanado} from './aplanar';
import {entintar} from './npr';
import {suavizarNormales} from './suavizar';

// A model generated by TRELLIS, ready for the ink style: normals smoothed, texture flattened, standing on y=0,
// centred on its footprint and scaled so its longest side measures `largo` scene units.
export type Generado = {archivo: string; largo: number; suavizado?: number; aplanado?: Aplanado | false; pastel?: number};

export const cargarGenerado = async ({archivo, largo, suavizado = 12, aplanado = {}, pastel = 0.12}: Generado) => {
	const g = await new GLTFLoader().loadAsync(staticFile(archivo));
	if (suavizado > 0) g.scene.traverse((o) => ((o as THREE.Mesh).isMesh ? suavizarNormales((o as THREE.Mesh).geometry, suavizado) : null));
	const o = entintar(g.scene, pastel, aplanado);
	const box = new THREE.Box3().setFromObject(o);
	const size = box.getSize(new THREE.Vector3());
	const c = box.getCenter(new THREE.Vector3());
	o.position.set(-c.x, -box.min.y, -c.z);
	const escala = new THREE.Group();
	escala.add(o);
	escala.scale.setScalar(largo / Math.max(size.x, size.y, size.z, 1e-6));
	const holder = new THREE.Group();
	holder.add(escala);
	holder.userData.medida = size.multiplyScalar(largo / Math.max(size.x, size.y, size.z, 1e-6));
	return holder;
};

// File format of each Kenney pack in config/kenney.json; packs are unpacked under public/kenney/<pack>/.
const FORMATO: Record<string, 'obj' | 'glb'> = {muebles: 'obj', fabrica: 'glb', casas: 'glb', campo: 'glb'};

// 'muebles/loungeSofa' → the catalogue model, as loaded (not yet inked or placed).
export const cargarKenney = async (ref: string): Promise<THREE.Object3D> => {
	const [pack] = ref.split('/');
	const formato = FORMATO[pack];
	if (!formato) throw new Error(`paquete Kenney desconocido: ${pack}`);
	const base = staticFile(`kenney/${ref}`);
	if (formato === 'glb') return (await new GLTFLoader().loadAsync(`${base}.glb`)).scene;
	const {MTLLoader} = await import('three/examples/jsm/loaders/MTLLoader.js');
	const {OBJLoader} = await import('three/examples/jsm/loaders/OBJLoader.js');
	const materials = await new MTLLoader().loadAsync(`${base}.mtl`);
	materials.preload();
	return new OBJLoader().setMaterials(materials).loadAsync(`${base}.obj`);
};

// Model sitting on y=0, centred on its footprint, so pieces are placed by their middle. With `largo`, also scaled
// so its longest side measures that many scene units.
export const asentar = (o: THREE.Object3D, largo?: number) => {
	const box = new THREE.Box3().setFromObject(o);
	const c = box.getCenter(new THREE.Vector3());
	const size = box.getSize(new THREE.Vector3());
	o.position.set(-c.x, -box.min.y, -c.z);
	const g = new THREE.Group();
	g.add(o);
	if (largo) g.scale.setScalar(largo / Math.max(size.x, size.y, size.z, 1e-6));
	const holder = new THREE.Group();
	holder.add(g);
	return holder;
};

// Slides an object along its own direction until its bounding box touches a wall plane (axis 'z' or 'x', at `en`).
export const contraPared = (o: THREE.Object3D, eje: 'x' | 'z', en: number) => {
	o.updateMatrixWorld(true);
	const box = new THREE.Box3().setFromObject(o);
	o.position[eje] += en - box.min[eje];
};
